<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import ImportPanel from './ImportPanel.vue'
import {profile} from './people'
type Row = Record<string,any>
const analysisRunning=ref(false)
const p=ref<Row|null>(null), projects=ref<Row[]>([]), step=ref(0), busy=ref(false), error=ref(''), notice=ref(''), selected=ref(''), selectedScene=ref(''), proposal=ref<Row|null>(null), history=ref<Row[]>([]), event=ref<Row|null>(null), zoom=ref(100)
const source=ref({title:'',citation:'',location:'',text:''})
const steps=['资料与画作','人物与边界','故事大纲','生成与审核','检查与导出']
const labels:Row={supported:'有依据',inference:'解释／推测',fiction:'虚构补充'}
const scene=computed(()=>p.value?.scenes.find((s:Row)=>s.id===selectedScene.value)||p.value?.scenes[0])
const allUnits=computed(()=>p.value?.scenes.flatMap((s:Row)=>s.units)||[])
const unit=computed(()=>allUnits.value.find((u:Row)=>u.id===selected.value))
const id=()=>crypto.randomUUID().slice(0,12)
async function api(path:string,method='GET',body?:any){const r=await fetch('/api'+path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body instanceof FormData?body:body?JSON.stringify(body):undefined});if(!r.ok){let v=await r.json();throw Error(typeof v.detail==='string'?v.detail:(v.detail?.message||'请求失败')+(v.detail?.characters?.length?'：'+v.detail.characters.map((c:Row)=>c.name).join('、'):''))}return r.json()}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function list(){projects.value=await api('/projects')}
async function load(pid:string){await run(async()=>{p.value=await api('/projects/'+pid);localStorage.setItem('animatedscroll-project',pid);proposal.value=null;await list()})}
async function sample(){await run(async()=>{p.value=await api('/sample?example=zhekan','POST',{});localStorage.setItem('animatedscroll-project',p.value!.id);await list()})}
async function create(){await run(async()=>{p.value=await api('/projects','POST',{});localStorage.setItem('animatedscroll-project',p.value!.id);await list()})}
async function persist(){p.value=await api('/projects/'+p.value!.id,'PUT',p.value);await list()}
async function save(){await run(async()=>{await persist();notice.value='已保存到本地'})}
async function generate(task:string,unitId=''){
 await run(async()=>{await persist();if(task!=='extract'&&(!p.value!.characters.length||blockers.value.length)){error.value='请先核对并确认：'+(blockers.value.map((c:Row)=>c.name).join('、')||'尚未建立人物');return}const result=await api(`/projects/${p.value!.id}/generate`,'POST',{version:p.value!.version,task,sceneId:scene.value?.id||'',unitId,instruction:instruction.value});if(result.proposal)proposal.value=result;else p.value=result;notice.value='生成完成，请人工核查';instruction.value=''})
}
const instruction=ref('')
const blockers=computed(()=>p.value?.characters.filter((c:Row)=>!c.confirmed)||[])
async function confirmRole(c:Row){await run(async()=>{const cid=c.id;await persist();p.value=await api(`/projects/${p.value!.id}/characters/${cid}/confirm`,'POST',{version:p.value!.version,characterId:cid})})}
function locateRole(cid:string){step.value=1;setTimeout(()=>document.getElementById('character-'+cid)?.scrollIntoView({block:'center',behavior:'smooth'}),0)}
async function apply(){await run(async()=>{p.value=await api(`/projects/${p.value!.id}/apply`,'POST',proposal.value);proposal.value=null;selected.value=''})}
async function addSource(){if(!source.value.text.trim()||!source.value.title.trim()){error.value='请填写资料标题及原文';return}p.value!.sources.push({...source.value,id:id(),version:1});source.value={title:'',citation:'',location:'',text:''};await save()}
async function importText(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f){source.value.text=await f.text();source.value.title ||= f.name}}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;await run(async()=>{await persist();const form=new FormData();form.append('file',f);p.value=await api(`/projects/${p.value!.id}/image?version=${p.value!.version}`,'POST',form)})}
let start:{x:number,y:number}|null=null
function point(e:PointerEvent){const r=(e.currentTarget as HTMLElement).getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
function down(e:PointerEvent){start=point(e);(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)}
function up(e:PointerEvent){if(!start)return;const end=point(e);if(Math.abs(end.x-start.x)>.01&&Math.abs(end.y-start.y)>.01)p.value!.annotations.push({id:id(),x:Math.min(start.x,end.x),y:Math.min(start.y,end.y),w:Math.abs(end.x-start.x),h:Math.abs(end.y-start.y),description:'',kind:'scene',characterId:'',confirmed:false});start=null}
function addCharacter(){p.value!.characters.push({id:id(),name:'新角色',identity:'',relationships:'',knowledge:'',evidence:'',confirmed:false})}
function addRef(){unit.value.references.push({sourceId:'',sourceVersion:1,annotationId:'',quote:''})}
function refChanged(r:Row){const s=p.value!.sources.find((s:Row)=>s.id===r.sourceId);r.sourceVersion=s?.version||1;r.annotationId=''}
async function audit(status:string){const selectedId=unit.value.id;await run(async()=>{await persist();const current=allUnits.value.find((u:Row)=>u.id===selectedId);current.status=status;await persist();notice.value='审核状态已保存'})}
async function logs(){await run(async()=>{history.value=await api(`/projects/${p.value!.id}/events`)})}
async function download(format:string,draft:boolean){await run(async()=>{await persist();const r=await fetch(`/api/projects/${p.value!.id}/export?format=${format}&draft=${draft}`);if(!r.ok)throw Error((await r.json()).detail);const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=`${draft?'draft':'approved'}-story.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
onMounted(async()=>{await run(list);if(projects.value.length){const last=localStorage.getItem('animatedscroll-project');await load(projects.value.find((p:Row)=>p.id===last)?.id||projects.value[0].id)}})
</script>

<template>
<header><div><h1>AnimatedScroll</h1></div><div class="actions"><select :disabled="busy||analysisRunning" :value="p?.id" @change="load(($event.target as HTMLSelectElement).value)"><option disabled value="">选择项目</option><option v-for="item in projects" :value="item.id">{{item.title}}</option></select><button :disabled="busy||analysisRunning" @click="create">＋ 新项目</button><button :disabled="busy||analysisRunning" @click="sample">载入折槛图示例</button><button class="primary" :disabled="busy||analysisRunning||!p" @click="save">保存版本</button></div></header>
<div v-if="error" class="banner error" role="alert">{{error}} <button :disabled="busy||analysisRunning" @click="p&&load(p.id)">重新加载已保存版本</button></div><div v-if="notice" class="banner">{{notice}}</div><div v-if="busy" class="banner" role="status">处理中，请稍候。模型生成可能需要约一分钟……</div>
<main v-if="p"><nav><button :disabled="busy||analysisRunning" v-for="(s,i) in steps" :class="{active:step===i}" @click="step=i"><b>0{{Number(i)+1}}</b>{{s}}</button></nav>
<fieldset :disabled="busy||analysisRunning"><div class="projectline"><input class="project-title" v-model="p.title"><span>本地项目 · v{{p.version}} · {{allUnits.filter((u:Row)=>u.status==='approved').length}} / {{allUnits.length}} 单元已批准</span></div>
<div v-if="p.reviewNotice" class="banner">{{p.reviewNotice}}</div>
<ImportPanel v-if="step===0" :key="p.id" :project="p" @replace="p=$event" @running="analysisRunning=$event"/>
<section v-if="step===1" class="columns"><article><h2>人物档案</h2><div class="actions"><button @click="addCharacter">手动添加角色</button></div><p>核对来源后确认。未知身份可保留角色称谓；已有人物时不自动覆盖。</p><div v-for="c in p.characters" :id="'character-'+c.id" class="card"><span class="role-state">{{c.confirmed?'● 资料已确认':'● 资料待确认'}}</span><p>{{profile(c)}}</p><details><summary>查看原文依据</summary><p v-for="m in c.mentions"><small>{{m.kind}} · {{m.start}}–{{m.end}} · v{{m.sourceVersion}}</small>{{m.quote}}</p><p v-if="!c.mentions?.length">{{c.evidence||'未提供原文定位'}}</p></details><input v-model="c.name" placeholder="名字／角色称谓"><label>身份<input v-model="c.identity" @input="c.summary=[c.identity,c.biography].filter(Boolean).join('；');c.confirmed=false"></label><label>经历（资料未提供时留空）<textarea v-model="c.biography" @input="c.summary=[c.identity,c.biography].filter(Boolean).join('；');c.confirmed=false"/></label><label>人物简介<textarea v-model="c.summary"/></label><label>人物关系<textarea v-model="c.relationships"/></label><label>依据与不确定性<textarea v-model="c.evidence"/></label><label>角色知道什么<textarea v-model="c.knowledge"/></label><button @click="confirmRole(c)">核对并确认人物资料</button><button @click="p.characters=p.characters.filter((v:Row)=>v.id!==c.id)">删除</button></div></article><article><h2>创作意图与历史边界</h2><label v-for="(label,key) in {theme:'主题',audience:'目标观众',tone:'叙述语气',goal:'故事目标',fixed:'不可改动的背景',allowed:'允许虚构的范围',forbidden:'禁止内容'}">{{label}}<textarea v-model="p.intent[key]"/></label></article></section>
<section v-if="step===2"><article><h2>故事大纲</h2><div v-if="blockers.length||!p.characters.length" class="banner"><b>生成前需要确认人物资料</b><p v-if="!p.characters.length">请先整理资料或添加人物。</p><button v-for="c in blockers" @click="locateRole(c.id)">核对 {{c.name}} →</button></div><label>故事场数（1–12）<input type="number" min="1" max="12" v-model.number="p.sceneCount"></label><button @click="p.scenes.push({id:id(),title:'新场景',goal:'',connection:'',characterIds:[],units:[]});p.sceneCount=p.scenes.length;p.outlineConfirmed=false">＋ 添加场景</button><p>先确认人物及历史边界，再生成大纲。正文生成后不覆盖大纲，可创建新项目探索其他版本。</p><button class="primary" :disabled="p.scenes.length>0||blockers.length>0||!p.characters.length" @click="generate('outline')">生成故事大纲 · 调用 LLM</button><div class="columns three"><div v-for="(s,i) in p.scenes" class="card"><small>SCENE {{Number(i)+1}}</small><button @click="p.scenes=p.scenes.filter((v:Row)=>v.id!==s.id);p.sceneCount=p.scenes.length||1;p.outlineConfirmed=false">删除场景</button><input v-model="s.title"><label>场景目标<textarea v-model="s.goal"/></label><label>前后关联<textarea v-model="s.connection"/></label><label v-for="c in p.characters"><input type="checkbox" :value="c.id" v-model="s.characterIds">{{c.name}}</label></div></div><label v-if="p.scenes.length"><input type="checkbox" v-model="p.outlineConfirmed">我已确认故事大纲与人物及历史边界一致</label></article></section>
<section v-if="step===3" class="review-layout"><article><h2>场景剧本</h2><select :value="scene?.id" @change="selectedScene=($event.target as HTMLSelectElement).value;selected=''"><option v-for="s in p.scenes" :value="s.id">{{s.title}}</option></select><template v-if="scene"><h3>{{scene.title}}</h3><p>{{scene.goal}}</p><button v-if="!scene.units.length" class="primary" @click="generate('scene')">生成这一场 · 调用 LLM</button><button v-for="u in scene.units" class="unit" :class="{chosen:selected===u.id}" @click="selected=u.id"><span class="tag" :class="u.category">{{labels[u.category]}}</span><small>{{u.status==='approved'?'已批准':u.status==='rejected'?'已拒绝':'待审核'}} {{u.locked?'· 已锁定':''}}</small><p>{{u.text}}</p></button><div class="card"><label>局部重写／分类要求<textarea v-model="instruction" placeholder="例如：保留背景，减少对人物动机的推测"/></label><div class="actions"><button @click="generate('rewrite')">重写本场 · 调用 LLM</button><button :disabled="!unit||unit.locked" @click="generate('rewrite',unit.id)">重写所选单元 · 调用 LLM</button><button :disabled="!scene.units.length" @click="generate('classify')">重新建议分类 · 调用 LLM</button></div></div></template><div v-else class="empty">请先生成并确认大纲</div></article>
<article><h2>依据与审核</h2><template v-if="unit"><fieldset :disabled="unit.locked"><label>内容<textarea rows="5" v-model="unit.text"/></label><label>类型<select v-model="unit.kind"><option value="event">事件</option><option value="action">动作</option><option value="dialogue">对白</option><option value="clue">线索</option></select></label><label>说话人物<select v-model="unit.speakerId"><option value="">无</option><option v-for="c in p.characters" :value="c.id">{{c.name}}</option></select></label><label>依据性质<select v-model="unit.category"><option v-for="(v,k) in labels" :value="k">{{v}}</option></select></label><label>推导过程／虚构用途<textarea v-model="unit.rationale"/></label><div v-for="r in unit.references" class="card"><select v-model="r.sourceId" @change="refChanged(r)"><option value="">选择资料或使用下方观察</option><option v-for="s in p.sources" :value="s.id">{{s.title}} · v{{s.version}}</option></select><select v-if="!r.sourceId" v-model="r.annotationId"><option value="">选择已确认观察</option><option v-for="a in p.annotations.filter((a:Row)=>a.confirmed)" :value="a.id">{{a.description}}</option></select><textarea v-model="r.quote" placeholder="逐字粘贴资料原文／观察描述"/><details v-if="r.sourceId"><summary>查看资料原文</summary><p class="pre">{{p.sources.find((s:Row)=>s.id===r.sourceId)?.text}}</p></details><button @click="unit.references=unit.references.filter((v:Row)=>v!==r)">移除引用</button></div><button @click="addRef">＋ 添加依据</button></fieldset><div class="actions"><button class="primary" @click="audit('approved')">批准</button><button @click="audit('rejected')">拒绝</button><button @click="audit('pending')">待审核</button><button @click="unit.locked=!unit.locked;save()">{{unit.locked?'解锁':'锁定'}}</button></div><small>锁定后需先解锁并保存才能修改。编辑内容后原批准状态会失效。</small></template><div v-else class="empty">选择左侧叙事单元查看依据</div></article></section>
<section v-if="step===4" class="columns"><article><h2>一致性与最终审核</h2><p>AI 检查属于建议。请处理人物知识、历史边界、引用及场景衔接问题；正式导出还会执行服务端校验。</p><button class="primary" @click="generate('check')">运行一致性检查 · 调用 LLM</button><div v-for="c in p.checks" class="card"><p>{{c.message}}</p><label><input type="checkbox" v-model="c.resolved">已处理／人工核查后接受</label></div><h3>导出故事包</h3><div class="actions"><button @click="download('json',true)">草稿 JSON</button><button @click="download('md',true)">草稿剧本</button><button class="primary" @click="download('json',false)">正式 JSON</button><button @click="download('md',false)">正式剧本</button></div></article><article><h2>创作过程与版本</h2><div class="actions"><button @click="logs">查看保存历史</button><button @click="download('jsonl',true)">日志 JSONL</button><button @click="download('csv',true)">日志 CSV</button></div><div class="history"><button v-for="e in [...history].reverse()" @click="event=e">v{{e.after.version}} · {{e.action}}<small>{{new Date(e.time).toLocaleString()}}</small></button></div><details v-if="event" open><summary>版本 {{event.after.version}} 的修改前后</summary><div class="columns"><pre>{{JSON.stringify(event.before,null,2)}}</pre><pre>{{JSON.stringify(event.after,null,2)}}</pre></div></details></article></section>
<footer><button v-if="step<4" class="primary" @click="step++">下一步 →</button></footer></fieldset>
<div v-if="proposal" class="modal"><article><h2>修改提案 · 比较后采用</h2><p>本场锁定内容会保留。采用后需要重新审核。</p><div class="columns"><div><h3>当前内容</h3><p v-for="u in scene.units.filter((u:Row)=>!proposal?.unitId||u.id===proposal.unitId)">{{u.text}}</p></div><div><h3>建议内容</h3><div v-for="u in proposal.proposal.units" class="card"><span class="tag" :class="u.category">{{labels[u.category]}}</span><p>{{u.text}}</p><small>{{u.rationale}}</small></div></div></div><div class="actions"><button :disabled="busy||analysisRunning" class="primary" @click="apply">采用提案</button><button :disabled="busy||analysisRunning" @click="proposal=null">保留原稿</button></div></article></div>
</main><div v-else class="welcome"><small>HISTORICALLY GROUNDED NARRATIVE</small><h2>让故事生动，让依据可见。</h2><p>从一段古画、几份资料和一个创作意图开始。</p><button class="primary" :disabled="busy||analysisRunning" @click="create">创建第一个项目</button></div>
</template>
